import React, { useMemo } from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  spring,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type VennDiagramProps = Record<string, any>;

const VennDiagram: React.FC<VennDiagramProps> = ({
  backgroundColor = "#111111",
  transparentBackground = false,
  durationInSeconds = 8,
  leftText = "goals",
  rightText = "people",
  primaryColor = "#ffffff",
  intersectionColor = "#4ade80",
  circleRadiusRatio = 0.28,
  overlapFactor = 0.45,
  textScale = 1.0,
}) => {
  useFontLoader(["Inter", "Roboto"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // --- Calculations ---
  // Responsive sizing
  const radius = Math.min(width, height) * circleRadiusRatio;
  const strokeWidth = Math.max(2, Math.min(width, height) * 0.008);
  
  // Animation Timing
  const entranceSpring = spring({
    frame,
    fps,
    config: { damping: 12, stiffness: 100 },
    delay: 5,
  });

  const mergeSpring = spring({
    frame: frame - 25,
    fps,
    config: { damping: 15, stiffness: 80 },
  });

  const textOpacity = interpolate(frame, [45, 65], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Calculate Positions
  // Start positions: Circles are further apart
  const startOffset = radius * 1.8; 
  // End positions: Circles overlap based on overlapFactor
  const endOffset = radius * (1 - overlapFactor);

  const currentOffset = interpolate(mergeSpring, [0, 1], [startOffset, endOffset]);

  const cxLeft = width / 2 - currentOffset;
  const cxRight = width / 2 + currentOffset;
  const cy = height / 2;

  // Text positioning logic:
  // When circles overlap, we want to center the text in the non-overlapping "crescent" area.
  // The geometric center of this available space on the X-axis is `width/2 - radius` for the left side
  // and `width/2 + radius` for the right side, regardless of the overlap amount (as long as overlap exists).
  // We use Math.min/Max to clamp the text to this position so it doesn't drift into the intersection
  // as the circles merge.
  const textLeftX = Math.min(cxLeft, width / 2 - radius);
  const textRightX = Math.max(cxRight, width / 2 + radius);

  // Colors
  const bg = transparentBackground ? "transparent" : backgroundColor;
  
  // Generate unique IDs for clip paths to avoid conflicts
  const clipId = useMemo(() => `clip-left-${Math.random().toString(36).substr(2, 9)}`, []);

  // Text Sizes
  const fontSize = radius * 0.35 * textScale;

  return (
    <AbsoluteFill style={{ backgroundColor: bg }}>
      <svg
        width={width}
        height={height}
        viewBox={`0 0 ${width} ${height}`}
        style={{ overflow: "visible" }}
      >
        <defs>
          {/* 
            Clip Path for Intersection:
            We define a shape that matches the LEFT circle.
            We will draw the RIGHT circle (green filled) inside this clip path.
            Result: Only the overlapping part of the Right circle is visible (as green).
          */}
          <clipPath id={clipId}>
            <circle cx={cxLeft} cy={cy} r={radius} />
          </clipPath>
        </defs>

        {/* Group for scaling entrance */}
        <g 
          style={{ 
            transformBox: "fill-box", 
            transformOrigin: "center",
            transform: `scale(${entranceSpring})`
          }}
        >
          {/* The Intersection Fill (Green) */}
          {/* This is the Right Circle, clipped by the Left Circle */}
          <circle
            cx={cxRight}
            cy={cy}
            r={radius}
            fill={intersectionColor}
            clipPath={`url(#${clipId})`}
            opacity={mergeSpring} // Fade in the intersection color as they merge
          />

          {/* Left Circle Outline */}
          <circle
            cx={cxLeft}
            cy={cy}
            r={radius}
            fill="none"
            stroke={primaryColor}
            strokeWidth={strokeWidth}
          />

          {/* Right Circle Outline */}
          <circle
            cx={cxRight}
            cy={cy}
            r={radius}
            fill="none"
            stroke={primaryColor}
            strokeWidth={strokeWidth}
          />
        </g>

        {/* Text Layers - Positioned explicitly in the non-overlapping portions */}
        <text
          x={textLeftX}
          y={cy}
          fill={primaryColor}
          fontFamily="Inter, Roboto, sans-serif"
          fontWeight="700"
          fontSize={fontSize}
          textAnchor="middle"
          dominantBaseline="middle"
          opacity={textOpacity}
          style={{ transition: "none" }}
        >
          {leftText}
        </text>

        <text
          x={textRightX}
          y={cy}
          fill={primaryColor}
          fontFamily="Inter, Roboto, sans-serif"
          fontWeight="700"
          fontSize={fontSize}
          textAnchor="middle"
          dominantBaseline="middle"
          opacity={textOpacity}
          style={{ transition: "none" }}
        >
          {rightText}
        </text>
      </svg>
    </AbsoluteFill>
  );
};

export default VennDiagram;